// The database of mavio.dev (docs/mavio-dev.md §2): better-auth's tables
// (auth-schema.ts, generated by `pnpm run generate-auth-schema`) and
// Mavio's own.
import { relations } from "drizzle-orm";
import { bigint, boolean, customType, index, integer, jsonb, pgTable, primaryKey, text, timestamp, uuid } from "drizzle-orm/pg-core";

import { user } from "./auth-schema.ts";

export * from "./auth-schema.ts";

const bytea = customType<{ data: Uint8Array; driverData: Uint8Array }>({
  dataType: () => "bytea",
  fromDriver: (v) => new Uint8Array(v),
});

const time = (name: string) => timestamp(name, { withTimezone: true, mode: "date" });

/** servers are the claimed servers, by the ID of their identity key. */
export const servers = pgTable(
  "servers",
  {
    id: text("id").primaryKey(),
    publicKey: bytea("public_key").notNull(),
    name: text("name").notNull().default(""),
    version: text("version").notNull().default(""),
    // An account administering a server cannot be deleted.
    administratorId: text("administrator_id")
      .notNull()
      .references(() => user.id, { onDelete: "restrict" }),
    // The cursor of the server's latest change.
    cursor: bigint("cursor", { mode: "number" }).notNull().default(0),
    claimedAt: time("claimed_at").notNull(),
    // The region of the relay the server keeps a connection to; empty
    // when it keeps none.
    relayRegion: text("relay_region").notNull().default(""),
    // The URLs the server published, best first.
    connections: jsonb("connections").$type<string[]>().notNull().default([]),
  },
  (t) => [index("servers_administrator_id_idx").on(t.administratorId)],
);

/** claimCodes are codes that claim a server for an account, by their SHA-256. */
export const claimCodes = pgTable("claim_codes", {
  codeHash: text("code_hash").primaryKey(),
  accountId: text("account_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  expiresAt: time("expires_at").notNull(),
});

/**
 * claimRequests are the claims servers asked for, which an account
 * confirms at /claim (docs/accounts.md §3.2), by a random ID: the server's
 * key, and the redirect URI, PKCE challenge, device key and state of the
 * web UI that started it. accountId is the account that confirmed it.
 */
export const claimRequests = pgTable(
  "claim_requests",
  {
    id: text("id").primaryKey(),
    serverId: text("server_id").notNull(),
    publicKey: bytea("public_key").notNull(),
    name: text("name").notNull().default(""),
    version: text("version").notNull().default(""),
    redirectUri: text("redirect_uri").notNull(),
    codeChallenge: text("code_challenge").notNull(),
    deviceKey: bytea("device_key").notNull(),
    state: text("state").notNull().default(""),
    accountId: text("account_id").references(() => user.id, { onDelete: "cascade" }),
    declined: boolean("declined").notNull().default(false),
    expiresAt: time("expires_at").notNull(),
  },
  (t) => [index("claim_requests_expires_at_idx").on(t.expiresAt)],
);

/**
 * authorizationCodes are the codes that sign accounts in to web UIs
 * (docs/accounts.md §6), by their SHA-256, exchanged once: a server's, or
 * app.mavio.dev's without a server.
 */
export const authorizationCodes = pgTable("authorization_codes", {
  codeHash: text("code_hash").primaryKey(),
  accountId: text("account_id")
    .notNull()
    .references(() => user.id, { onDelete: "cascade" }),
  serverId: text("server_id").references(() => servers.id, { onDelete: "cascade" }),
  redirectUri: text("redirect_uri").notNull(),
  codeChallenge: text("code_challenge").notNull(),
  deviceKey: bytea("device_key").notNull(),
  expiresAt: time("expires_at").notNull(),
});

/**
 * deviceSessions are the sessions of devices' keys (docs/mavio-dev.md §2):
 * the web UIs' and the apps', whose short access tokens a device renews by
 * signing the time with its key, later than its last renewal.
 */
export const deviceSessions = pgTable(
  "device_sessions",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    // The client the session was given to: a server's ID, "app" or an app's reverse-DNS ID.
    clientId: text("client_id").notNull(),
    deviceKey: bytea("device_key").notNull(),
    // The time, in milliseconds, the device signed for its last renewal.
    renewedAt: bigint("renewed_at", { mode: "number" }).notNull().default(0),
    createdAt: time("created_at").notNull(),
    lastSeenAt: time("last_seen_at").notNull(),
  },
  (t) => [index("device_sessions_account_id_idx").on(t.accountId)],
);

/**
 * linkCodes are the codes that sign devices in at /link (RFC 8628), by
 * the SHA-256 of their device codes: the client and device key asking,
 * and the account that approved it.
 */
export const linkCodes = pgTable(
  "link_codes",
  {
    deviceCodeHash: text("device_code_hash").primaryKey(),
    userCode: text("user_code").notNull().unique(),
    clientId: text("client_id").notNull(),
    deviceKey: bytea("device_key").notNull(),
    accountId: text("account_id").references(() => user.id, { onDelete: "cascade" }),
    denied: boolean("denied").notNull().default(false),
    polledAt: time("polled_at"),
    expiresAt: time("expires_at").notNull(),
  },
  (t) => [index("link_codes_expires_at_idx").on(t.expiresAt)],
);

/** serverTokens are the IDs of servers' JWTs, accepted once each until they expire. */
export const serverTokens = pgTable(
  "server_tokens",
  {
    id: text("id").primaryKey(),
    expiresAt: time("expires_at").notNull(),
  },
  (t) => [index("server_tokens_expires_at_idx").on(t.expiresAt)],
);

/** serverLibraries are the libraries servers published. */
export const serverLibraries = pgTable(
  "server_libraries",
  {
    serverId: text("server_id")
      .notNull()
      .references(() => servers.id, { onDelete: "cascade" }),
    id: uuid("id").notNull(),
    name: text("name").notNull(),
    kind: text("kind").notNull(),
  },
  (t) => [primaryKey({ columns: [t.serverId, t.id] })],
);

/**
 * accessRecords are the library access records (docs/accounts.md §3.3):
 * access is a mavio.cloud.v1.Access in protobuf JSON, and a record is an
 * invitation until its account accepts it.
 */
export const accessRecords = pgTable(
  "access_records",
  {
    serverId: text("server_id")
      .notNull()
      .references(() => servers.id, { onDelete: "cascade" }),
    accountId: text("account_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    access: jsonb("access").notNull(),
    invitation: boolean("invitation").notNull(),
    createdAt: time("created_at").notNull(),
    updatedAt: time("updated_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.serverId, t.accountId] }), index("access_records_account_id_idx").on(t.accountId)],
);

/** changes are each server's changes, a mavio.cloud.v1.Change in protobuf JSON by cursor. */
export const changes = pgTable(
  "changes",
  {
    serverId: text("server_id")
      .notNull()
      .references(() => servers.id, { onDelete: "cascade" }),
    cursor: bigint("cursor", { mode: "number" }).notNull(),
    change: jsonb("change").notNull(),
    createdAt: time("created_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.serverId, t.cursor] })],
);

/**
 * homes are the Homes (docs/accounts.md §3.5); an account administers at
 * most one, and cannot be deleted while it does.
 */
export const homes = pgTable("homes", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  administratorId: text("administrator_id")
    .notNull()
    .unique()
    .references(() => user.id, { onDelete: "restrict" }),
  createdAt: time("created_at").notNull(),
});

/** homeMembers are the accounts of the Homes, their administrators included; an account belongs to at most one. */
export const homeMembers = pgTable(
  "home_members",
  {
    accountId: text("account_id")
      .primaryKey()
      .references(() => user.id, { onDelete: "cascade" }),
    homeId: text("home_id")
      .notNull()
      .references(() => homes.id, { onDelete: "cascade" }),
    joinedAt: time("joined_at").notNull(),
  },
  (t) => [index("home_members_home_id_idx").on(t.homeId)],
);

/**
 * homeInvitations are invitations into Homes: offers are the access
 * records offered, [{serverId, access}] with access a
 * mavio.cloud.v1.Access in protobuf JSON.
 */
export const homeInvitations = pgTable(
  "home_invitations",
  {
    homeId: text("home_id")
      .notNull()
      .references(() => homes.id, { onDelete: "cascade" }),
    accountId: text("account_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    offers: jsonb("offers").notNull(),
    createdAt: time("created_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.homeId, t.accountId] }), index("home_invitations_account_id_idx").on(t.accountId)],
);

/** friendships are friends (docs/accounts.md §3.4), requests until accepted. */
export const friendships = pgTable(
  "friendships",
  {
    requesterId: text("requester_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    addresseeId: text("addressee_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accepted: boolean("accepted").notNull(),
    createdAt: time("created_at").notNull(),
  },
  (t) => [primaryKey({ columns: [t.requesterId, t.addresseeId] }), index("friendships_addressee_id_idx").on(t.addresseeId)],
);

/** pins are accounts' PINs, which guard switching to them, with the throttling of wrong ones. */
export const pins = pgTable("pins", {
  accountId: text("account_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  hash: text("hash").notNull(),
  // Wrong PINs since the last right one.
  failures: integer("failures").notNull().default(0),
  // When switching to the account may be tried again.
  retryAt: time("retry_at"),
});

/** passes are accounts' Mavio Passes (docs/accounts.md §3.7). */
export const passes = pgTable("passes", {
  accountId: text("account_id")
    .primaryKey()
    .references(() => user.id, { onDelete: "cascade" }),
  expiresAt: time("expires_at").notNull(),
});

export const serversRelations = relations(servers, ({ one, many }) => ({
  administrator: one(user, { fields: [servers.administratorId], references: [user.id] }),
  libraries: many(serverLibraries),
  accessRecords: many(accessRecords),
}));

export const serverLibrariesRelations = relations(serverLibraries, ({ one }) => ({
  server: one(servers, { fields: [serverLibraries.serverId], references: [servers.id] }),
}));

export const accessRecordsRelations = relations(accessRecords, ({ one }) => ({
  server: one(servers, { fields: [accessRecords.serverId], references: [servers.id] }),
  account: one(user, { fields: [accessRecords.accountId], references: [user.id] }),
}));

export const homesRelations = relations(homes, ({ one, many }) => ({
  administrator: one(user, { fields: [homes.administratorId], references: [user.id] }),
  members: many(homeMembers),
  invitations: many(homeInvitations),
}));

export const homeMembersRelations = relations(homeMembers, ({ one }) => ({
  home: one(homes, { fields: [homeMembers.homeId], references: [homes.id] }),
  account: one(user, { fields: [homeMembers.accountId], references: [user.id] }),
}));

export const homeInvitationsRelations = relations(homeInvitations, ({ one }) => ({
  home: one(homes, { fields: [homeInvitations.homeId], references: [homes.id] }),
  account: one(user, { fields: [homeInvitations.accountId], references: [user.id] }),
}));
